\begin{definition}[Registration-based encryption, syntax]\label{def:rbe2}
A \emph{registration-based encryption} (RBE) scheme is a tuple of PPT algorithms $\Pi = (\mathsf{Gen}, \mathsf{Reg}, \mathsf{Enc}, \mathsf{Upd}, \mathsf{Dec})$, used together with a common random string $\mathsf{crs} \leftarrow \{0,1\}^{\mathrm{poly}(\kappa)}$ sampled once and published:
\begin{itemize}
  \item $\mathsf{Gen}(1^{\kappa}) \to (\mathsf{pk},\mathsf{sk})$, run locally by a registering party;
  \item $\mathsf{Reg}^{[\mathsf{aux}]}(\mathsf{crs},\mathsf{pp},\mathsf{id},\mathsf{pk}) \to \mathsf{pp}'$, \emph{deterministic}, run by the \emph{key curator} (KC) with read/write access to an auxiliary state $\mathsf{aux}$ it may modify; the system starts with $\mathsf{pp} = \mathsf{aux} = \bot$;
  \item $\mathsf{Enc}(\mathsf{crs},\mathsf{pp},\mathsf{id},m) \to \mathsf{ct}$;
  \item $\mathsf{Upd}^{\mathsf{aux}}(\mathsf{pp},\mathsf{id},\mathsf{pk}) \to u$, \emph{deterministic}, run by the KC with read-only access to $\mathsf{aux}$;
  \item $\mathsf{Dec}(\mathsf{sk},u,\mathsf{ct}) \to m$, \emph{deterministic}, outputting a message $m \in \{0,1\}^{*}$, or $\bot$ (syntax error), or $\mathsf{GetUpd}$ (indicating that more recent update information than $u$ may be needed).
\end{itemize}
\end{definition}

\begin{definition}[Forward DAG]\label{def:dag}
A \emph{forward DAG} is a directed acyclic graph $G$ with vertex set $\mathbb{N}$ (or $[n]$) such that every edge $(i,j) \in G$ satisfies $i \le j$.
\end{definition}

\begin{definition}[$\rho$-completeness with fixed update graph $G$]\label{def:comp2}
Let $G$ be an infinite forward DAG. Consider the following game between a challenger $\mathcal{C}$ and a computationally unbounded adversary $\mathcal{A}$ limited to $\mathrm{poly}(\kappa)$ rounds. $\mathcal{C}$ sets $\mathsf{pp} = \mathsf{aux} = u = \bot$, $\mathcal{D} = \emptyset$, $\mathsf{id}^{*} = \bot$, $t = 0$, samples $\mathsf{crs}$ and sends it to $\mathcal{A}$. In each round $\mathcal{A}$ performs exactly one of:
\begin{enumerate}
  \item \textbf{Registering an identity.} Either (i) $\mathcal{A}$ sends a pair $(\mathsf{id},\mathsf{pk})$ with $\mathsf{id} \notin \mathcal{D}$, where $\mathsf{pk}$ may be arbitrary and adversarial, and $\mathcal{C}$ sets $\mathsf{pp} := \mathsf{Reg}^{[\mathsf{aux}]}(\mathsf{crs},\mathsf{pp},\mathsf{id},\mathsf{pk})$, $\mathcal{D} := \mathcal{D}\cup\{\mathsf{id}\}$; or (ii) if $\mathsf{id}^{*} = \bot$, $\mathcal{A}$ sends $\mathsf{id}^{*} \notin \mathcal{D}$ and $\mathcal{C}$ samples $(\mathsf{pk}^{*},\mathsf{sk}^{*}) \leftarrow \mathsf{Gen}(1^{\kappa})$, sets $\mathsf{pp} := \mathsf{Reg}^{[\mathsf{aux}]}(\mathsf{crs},\mathsf{pp},\mathsf{id}^{*},\mathsf{pk}^{*})$, $\mathcal{D} := \mathcal{D}\cup\{\mathsf{id}^{*}\}$, and returns $\mathsf{pk}^{*}$ to $\mathcal{A}$. In either case, if $\mathsf{id}^{*} \neq \bot$, letting $i$ be the registration index of $\mathsf{id}^{*}$ and $j$ the registration index of the identity just registered, $\mathcal{C}$ sets $u := \mathsf{Upd}^{\mathsf{aux}}(\mathsf{pp},\mathsf{id}^{*},\mathsf{pk}^{*})$ whenever $(i,j) \in G$, and does nothing otherwise.
  \item \textbf{Encrypting for the target} (allowed only if $\mathsf{id}^{*} \neq \bot$). $\mathcal{C}$ sets $t := t+1$; $\mathcal{A}$ sends $m_t$; $\mathcal{C}$ sets $m'_t := m_t$ and returns $\mathsf{ct}_t \leftarrow \mathsf{Enc}(\mathsf{crs},\mathsf{pp},\mathsf{id}^{*},m_t)$.
  \item \textbf{Decrypting for the target.} $\mathcal{A}$ sends $j \in [t]$; $\mathcal{C}$ sets $m'_j := \mathsf{Dec}(\mathsf{sk}^{*},u,\mathsf{ct}_j)$.
\end{enumerate}
$\mathcal{A}$ wins if $m'_j \neq m_j$ for some $j \in [t]$; in particular $\mathcal{A}$ wins if decryption ever returns $\mathsf{GetUpd}$, since updates are pushed only as $G$ dictates. The scheme is \emph{$\rho$-complete with fixed update graph $G$} if every such $\mathcal{A}$ wins with probability at most $1-\rho$. Thus the number of updates received by identity $i$ while the first $n$ identities register is $|\{j \le n : (i,j) \in G\}|$, and the worst case over identities is $\deg^{+}(G_n)$.
\end{definition}

\begin{definition}[$0$-corruption security]\label{def:sec2}
Consider the following game between a PPT adversary $\mathcal{A}$ and a challenger $\mathcal{C}$. $\mathcal{C}$ sets $\mathsf{pp} = \mathsf{aux} = \bot$, $\mathcal{D} = \emptyset$, samples $\mathsf{crs}$ and sends it to $\mathcal{A}$. Repeatedly, $\mathcal{A}$ sends some $\mathsf{id} \notin \mathcal{D}$; $\mathcal{C}$ samples $(\mathsf{pk},\mathsf{sk}) \leftarrow \mathsf{Gen}(1^{\kappa})$, sets $\mathsf{pp} := \mathsf{Reg}^{[\mathsf{aux}]}(\mathsf{crs},\mathsf{pp},\mathsf{id},\mathsf{pk})$, $\mathcal{D} := \mathcal{D}\cup\{\mathsf{id}\}$ and returns $\mathsf{pk}$ to $\mathcal{A}$; the adversary never receives a secret key. Then $\mathcal{A}$ sends a target $\mathsf{id}^{*}$ and messages $m_0,m_1$ with $|m_0| = |m_1|$; $\mathcal{C}$ samples $b \leftarrow \{0,1\}$ and returns $\mathsf{ct} \leftarrow \mathsf{Enc}(\mathsf{crs},\mathsf{pp},\mathsf{id}^{*},m_b)$; $\mathcal{A}$ outputs $b'$ and wins if $b' = b$. The scheme is \emph{$0$-corruption secure} if every PPT $\mathcal{A}$ wins with probability at most $\tfrac12 + \mathrm{negl}(\kappa)$.
\end{definition}
